PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE usuarios (   id INTEGER PRIMARY KEY,   username TEXT UNIQUE,   pin TEXT,   rol TEXT,   activo INTEGER,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE entradas (   id INTEGER PRIMARY KEY,   placa TEXT UNIQUE,   cliente TEXT,   marca TEXT,   modelo TEXT,   color TEXT,   telefono TEXT,   observaciones TEXT,   usuario_registra TEXT,   hora_entrada DATETIME DEFAULT CURRENT_TIMESTAMP,   fotos JSON );
CREATE TABLE salidas (   id INTEGER PRIMARY KEY,   placa TEXT,   cliente TEXT,   hora_salida DATETIME,   comentarios TEXT,   precio DECIMAL,   usuario_registra TEXT,   entrada_id INTEGER,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  pin_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('driver','supervisor','director')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, cedula TEXT, sector TEXT, phone TEXT, emergency_contact TEXT, emergency_phone TEXT, is_allergic TEXT, current_session_id INTEGER, bank_name TEXT, bank_account TEXT, status TEXT, cargo TEXT, birth_date TEXT, email TEXT, address TEXT, photo_url TEXT, admin_level INTEGER DEFAULT 3, op_level INTEGER DEFAULT 4, username TEXT, password TEXT, is_active INTEGER DEFAULT 1, carnet_url TEXT, profile_admin TEXT, profile_opera TEXT, eye_id TEXT, last_login DATETIME, current_device TEXT, whatsapp_apikey TEXT);
CREATE TABLE IF NOT EXISTS "vehicles_old" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  plate TEXT NOT NULL UNIQUE,
  brand TEXT,
  model TEXT,
  color TEXT,
  status TEXT NOT NULL CHECK(status IN ('checkin','parked','requested','delivering','delivered','pending_retrieval','retrieved')),
  ticket_code TEXT UNIQUE,
  owner_name TEXT,
  owner_phone TEXT,
  owner_id_ref TEXT,
  parking_spot TEXT,
  damage_notes TEXT,
  fee_amount REAL,
  fee_paid INTEGER DEFAULT 0,
  payment_method TEXT,
  valet_in TEXT,
  valet_out TEXT,
  check_in_at TEXT DEFAULT CURRENT_TIMESTAMP,
  check_out_at TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, key_hook TEXT, damage_json TEXT, requested_at DATETIME);
CREATE TABLE slots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  zone TEXT NOT NULL,
  number INTEGER NOT NULL,
  is_free INTEGER DEFAULT 1
);
CREATE TABLE reservations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  confirm_code TEXT NOT NULL UNIQUE,
  owner_name TEXT NOT NULL,
  owner_phone TEXT NOT NULL,
  plate TEXT,
  brand TEXT,
  model TEXT,
  expected_arrival TEXT NOT NULL,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'arrived', 'cancelled')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, endpoint TEXT UNIQUE, keys_p256dh TEXT, keys_auth TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shifts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, start_at DATETIME DEFAULT CURRENT_TIMESTAMP, end_at DATETIME, total_minutes INTEGER, status TEXT DEFAULT 'active');
CREATE TABLE vehicles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    plate TEXT NOT NULL,
    brand TEXT,
    model TEXT,
    color TEXT,
    status TEXT NOT NULL,
    ticket_code TEXT UNIQUE,
    owner_name TEXT,
    owner_phone TEXT,
    owner_id_ref TEXT,
    parking_spot TEXT,
    damage_notes TEXT,
    damage_json TEXT,
    fee_amount REAL,
    fee_paid INTEGER DEFAULT 0,
    payment_method TEXT,
    valet_in TEXT,
    valet_out TEXT,
    check_in_at TEXT DEFAULT CURRENT_TIMESTAMP,
    check_out_at TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  , session_id INTEGER, daily_seq INTEGER, owner_email TEXT, auth_token_1 TEXT, auth_token_2 TEXT, retrieval_token TEXT, conformity_signed INTEGER DEFAULT 0, vehicle_type TEXT DEFAULT 'car');
CREATE TABLE events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    vehicle_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    event_type TEXT NOT NULL,
    key_hook TEXT,
    slot_id INTEGER,
    ts TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
  );
CREATE TABLE photos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    vehicle_id INTEGER NOT NULL,
    url TEXT NOT NULL,
    FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
  );
CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    vehicle_id INTEGER NOT NULL,
    from_role TEXT NOT NULL,
    to_role TEXT NOT NULL,
    text TEXT NOT NULL,
    ts TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
  );
CREATE TABLE metrics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    vehicle_id INTEGER NOT NULL,
    avg_time INTEGER,
    alerts_count INTEGER DEFAULT 0,
    FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
  );
CREATE TABLE sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, status TEXT DEFAULT 'open', started_at TEXT DEFAULT CURRENT_TIMESTAMP, ended_at TEXT, type TEXT DEFAULT 'valet', client TEXT, phone TEXT, address TEXT, supervisor_id INTEGER REFERENCES users(id), contact_name TEXT, email TEXT, observations TEXT, internal_key TEXT, convocation_time TEXT, event_start_time TEXT, event_end_time TEXT, notified INTEGER DEFAULT 0, event_end_date TEXT, budget_id TEXT);
CREATE TABLE modules (
  id TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  category TEXT NOT NULL CHECK(category IN ('Servicios', 'Operaciones')),
  is_active INTEGER DEFAULT 1
);
CREATE TABLE role_permissions (
  role TEXT NOT NULL,
  module_id TEXT NOT NULL,
  can_view INTEGER DEFAULT 1,
  PRIMARY KEY(role, module_id),
  FOREIGN KEY(module_id) REFERENCES modules(id)
);
CREATE TABLE payroll_rates (id INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT NOT NULL UNIQUE, rate REAL NOT NULL, description TEXT);
CREATE TABLE payroll_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, session_id INTEGER NOT NULL, date TEXT NOT NULL, role_at_event TEXT NOT NULL, bank_name TEXT, bank_account TEXT, amount REAL, status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')), approved_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE equivalences (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL CHECK(category IN ('brand', 'model', 'color')),
  original_value TEXT NOT NULL,
  standard_value TEXT NOT NULL,
  UNIQUE(category, original_value)
);
CREATE TABLE staff_attendance (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      session_id INTEGER,
      type TEXT, -- 'entry', 'exit', 'break_start', 'break_end'
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE assets (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('equipment', 'vehicle', 'other')), status TEXT DEFAULT 'available', description TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE locations (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_id INTEGER NOT NULL, entity_type TEXT NOT NULL CHECK(entity_type IN ('staff', 'asset')), latitude REAL NOT NULL, longitude REAL NOT NULL, accuracy REAL, ts TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE geofences (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  latitude REAL NOT NULL,
  longitude REAL NOT NULL,
  radius INTEGER NOT NULL,
  type TEXT CHECK(type IN ('office', 'client', 'danger_zone')) DEFAULT 'office',
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE geofence_alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  geofence_id INTEGER NOT NULL,
  alert_type TEXT CHECK(alert_type IN ('entry', 'exit')),
  ts TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(user_id) REFERENCES users(id),
  FOREIGN KEY(geofence_id) REFERENCES geofences(id)
);
CREATE TABLE tracking_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, requested_by INTEGER NOT NULL, status TEXT DEFAULT 'pending', expires_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE access_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id INTEGER NOT NULL,
  visitor_name TEXT,
  visitor_id_ref TEXT,
  visitor_type TEXT,
  visitor_phone TEXT,
  visitor_email TEXT,
  comments TEXT,
  company_name TEXT,
  vehicle_details TEXT,
  activity_desc TEXT,
  status TEXT DEFAULT 'in',
  entry_at TEXT DEFAULT CURRENT_TIMESTAMP,
  exit_at TEXT,
  operator_id INTEGER,
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
CREATE TABLE guest_list (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  id_ref TEXT,
  visitor_type TEXT,
  notes TEXT,
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
CREATE TABLE audit_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      action TEXT,
      details TEXT,
      ip TEXT,
      device TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE web_sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  ip TEXT,
  device TEXT,
  login_at TEXT DEFAULT CURRENT_TIMESTAMP,
  last_activity_at TEXT DEFAULT CURRENT_TIMESTAMP,
  logout_at TEXT,
  is_active INTEGER DEFAULT 1,
  FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE TABLE job_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, cedula TEXT NOT NULL, email TEXT, phone TEXT, address TEXT, birth_date TEXT, experience TEXT, photo_url TEXT, status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'interviewed', 'hired', 'rejected')), created_at TEXT DEFAULT CURRENT_TIMESTAMP, category TEXT DEFAULT 'postulación');
CREATE TABLE event_reports (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      session_id INTEGER NOT NULL,
      session_name TEXT,
      event_type TEXT,
      closed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      total_vehicles INTEGER DEFAULT 0,
      total_staff INTEGER DEFAULT 0,
      pdf_r2_key TEXT,
      excel_r2_key TEXT,
      summary_json TEXT
    , sent_emails_history TEXT DEFAULT '[]');
CREATE TABLE chat_messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_id INTEGER NOT NULL,
        recipient_id INTEGER,
        session_id INTEGER,
        message TEXT NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY(sender_id) REFERENCES users(id),
        FOREIGN KEY(recipient_id) REFERENCES users(id),
        FOREIGN KEY(session_id) REFERENCES sessions(id)
      );
CREATE TABLE valet_clients (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, email TEXT, event_type TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE budgets (
  id TEXT PRIMARY KEY,
  empresa TEXT,
  evento TEXT,
  fecha TEXT,
  monto TEXT,
  estatus TEXT DEFAULT 'GENERADO',
  action TEXT,
  form_data TEXT, -- JSON
  items_data TEXT, -- JSON
  timestamp INTEGER,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE budget_seq (
  year INTEGER PRIMARY KEY,
  seq INTEGER DEFAULT 0
);
CREATE TABLE social_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  platform TEXT NOT NULL, -- 'tiktok', 'instagram'
  followers INTEGER,
  following INTEGER,
  posts_count INTEGER,
  avg_engagement REAL,
  date TEXT DEFAULT (date('now')),
  UNIQUE(platform, date)
);
CREATE TABLE social_content (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  platform TEXT NOT NULL,
  post_id TEXT,
  type TEXT, -- 'video', 'image', 'reel'
  content_text TEXT,
  media_url TEXT,
  likes INTEGER,
  comments_count INTEGER,
  sentiment_score REAL, -- -1 to 1
  perceived_message TEXT,
  published_at TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE social_insights (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT,
  content TEXT,
  category TEXT, -- 'growth', 'loyalty', 'sales'
  date TEXT DEFAULT (date('now'))
);
CREATE TABLE rentals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  budget_id TEXT NOT NULL UNIQUE,
  status TEXT DEFAULT 'planning' CHECK(status IN ('planning', 'delivering', 'delivered', 'retrieving', 'completed')),
  delivery_photos TEXT,
  retrieval_photos TEXT,
  delivery_signature TEXT,
  retrieval_signature TEXT,
  notes TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(budget_id) REFERENCES budgets(id)
);
CREATE TABLE access_control_guests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  qr_code_id TEXT UNIQUE NOT NULL,
  status TEXT DEFAULT 'PENDING' CHECK(status IN ('PENDING', 'CHECKED_IN')),
  guest_type TEXT DEFAULT 'INVITADO', -- INVITADO, VIP, STAFF, PROVEEDOR
  phone TEXT,
  email TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  checked_in_at TEXT,
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
CREATE TABLE user_permissions_matrix (
      user_id INTEGER PRIMARY KEY,
      valet_ve INTEGER DEFAULT 0,
      valet_mod INTEGER DEFAULT 0,
      eventos_ve INTEGER DEFAULT 0,
      eventos_mod INTEGER DEFAULT 0,
      admin_ve INTEGER DEFAULT 0,
      admin_mod INTEGER DEFAULT 0,
      vip_ve INTEGER DEFAULT 0,
      vip_mod INTEGER DEFAULT 0,
      seg_ve INTEGER DEFAULT 0,
      seg_mod INTEGER DEFAULT 0,
      FOREIGN KEY(user_id) REFERENCES users(id)
    );
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_users_name ON users(name);
